import{_ as a,o as n,a as p,b as c}from"./app.BGziXukh.js";const l="/ascendc.github.io/assets/pending_data.CNcmO89t.png",_=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C算子开发指南","link":"/guide/getting_started/ascend_c_overview_and_learning_path"},{"text":"算子实践参考","link":"/guide/operator_practice/operator_practice"},{"text":"SIMD算子性能优化","link":"/guide/operator_practice/simd_operator_optimization/simd_operator_optimization"},{"text":"内存访问","link":"/guide/operator_practice/simd_operator_optimization/memory_access/memory_access"},{"text":"高效的使用搬运API","link":"/guide/operator_practice/simd_operator_optimization/memory_access/efficient_transfer_api"}]},"headers":[],"relativePath":"guide/operator_practice/simd_operator_optimization/memory_access/efficient_transfer_api.md","filePath":"guide/operator_practice/simd_operator_optimization/memory_access/efficient_transfer_api.md","outlineHeaders":[{"level":2,"title":"优化原理","slug":"优化原理","link":"#优化原理"},{"level":2,"title":"不同API下的实现","slug":"不同API下的实现","link":"#不同API下的实现"},{"level":3,"title":"C API","slug":"C-API","link":"#C-API"},{"level":3,"title":"Basic API","slug":"Basic-API","link":"#Basic-API"}],"lastUpdated":1795433433000}'),t={name:"guide/operator_practice/simd_operator_optimization/memory_access/efficient_transfer_api.md"};function o(i,s,e,w,r,d){return n(),p("div",null,[...s[0]||(s[0]=[c('<div><article class="markdown-body"><h1>高效的使用搬运API</h1><p>【优先级】高</p><div class="callout callout-note"><p class="callout-title"><svg class="callout-icon" viewBox="0 0 16 16" width="16" height="16"><path d="M0 8a8 8 0 1 1 16 0A8 8 0 0 1 0 8Zm8-6.5a6.5 6.5 0 1 0 0 13 6.5 6.5 0 0 0 0-13ZM6.5 7.75A.75.75 0 0 1 7.25 7h1a.75.75 0 0 1 .75.75v2.75h.25a.75.75 0 0 1 0 1.5h-2a.75.75 0 0 1 0-1.5h.25v-2h-.25a.75.75 0 0 1-.75-.75ZM8 6a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"></path></svg>说明</p><p>本文介绍的优化建议不依赖具体API。为便于理解，“优化原理”小节沿用Basic API的接口及术语进行说明；不同API下的具体实现请参见<a href="#different_api_implementations">不同API下的实现</a>。</p></div><h2 id="优化原理">优化原理<a class="header-anchor" href="#优化原理">​</a></h2><p>【描述】在使用搬运API时，应该尽可能地通过配置搬运控制参数实现连续搬运或者固定间隔搬运，避免使用for循环，二者效率差距极大。如下图示例，图片的每一行为16KB，需要从每一行中搬运前2KB，针对这种场景，使用for循环遍历每行，每次仅能搬运<strong>2</strong>KB。若直接配置DataCopyParams的blockCount、blockLen、srcStride和dstStride，则可以达到一次搬完的效果，每次搬运<strong>32</strong>KB；参考<a href="transfer_larger_data_blocks.html">尽量一次搬运较大的数据块</a>章节介绍的搬运数据量和实际带宽的关系，建议一次搬完。</p><p><strong>图1</strong> 待搬运数据排布<br><img src="'+l+`" alt title="待搬运数据排布"></p><p>【反例】</p><p>从GM上每行16KB中搬运前2KB数据，共16行。使用for循环逐行提交搬运，每次搬运2KB，共提交16次。</p><p>【正例】</p><p>将16行的块数、每行2KB的有效长度以及行间步长交给搬运接口，一次提交搬运，在UB中连续存放32KB数据。</p><h2 id="不同API下的实现">不同API下的实现<a id="different_api_implementations"></a><a class="header-anchor" href="#不同API下的实现">​</a></h2><div data-filter="950"><div class="callout callout-note"><p class="callout-title"><svg class="callout-icon" viewBox="0 0 16 16" width="16" height="16"><path d="M0 8a8 8 0 1 1 16 0A8 8 0 0 1 0 8Zm8-6.5a6.5 6.5 0 1 0 0 13 6.5 6.5 0 0 0 0-13ZM6.5 7.75A.75.75 0 0 1 7.25 7h1a.75.75 0 0 1 .75.75v2.75h.25a.75.75 0 0 1 0 1.5h-2a.75.75 0 0 1 0-1.5h.25v-2h-.25a.75.75 0 0 1-.75-.75ZM8 6a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"></path></svg>说明</p><p>C API实现部分仅适用于Ascend 950PR&amp;950DT系列产品。</p></div><h3 id="C-API">C API<a class="header-anchor" href="#C-API">​</a></h3><p>通过<a href="../../../../api/SIMD-API/c_api/vector_datamove/asc_copy_gm2ub_align/asc_copy_gm2ub_align_arch_3510.html">asc_copy_gm2ub_align</a>搬运数据，显式配置块数、块长度和源、目的步长。<code>tensorGM</code>至少指向16行、每行4096个float的GM输入，<code>tensorIn</code>至少容纳8192个float，且UB起始地址32字节对齐。</p><p>【反例】</p><p>每次搬运一行的有效数据，循环提交16次搬运。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="cp">#include</span><span class="w"> </span><span class="cpf">&quot;c_api/asc_simd.h&quot;</span>

<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">CopyRowsCBad</span><span class="p">(</span><span class="n">__ubuf__</span><span class="w"> </span><span class="kt">float</span><span class="o">*</span><span class="w"> </span><span class="n">tensorIn</span><span class="p">,</span><span class="w"> </span><span class="n">__gm__</span><span class="w"> </span><span class="kt">float</span><span class="o">*</span><span class="w"> </span><span class="n">tensorGM</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="k">constexpr</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">copyWidth</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">2</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="mi">1024</span><span class="w"> </span><span class="o">/</span><span class="w"> </span><span class="k">sizeof</span><span class="p">(</span><span class="kt">float</span><span class="p">);</span>
<span class="w">    </span><span class="k">constexpr</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">imgWidth</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">16</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="mi">1024</span><span class="w"> </span><span class="o">/</span><span class="w"> </span><span class="k">sizeof</span><span class="p">(</span><span class="kt">float</span><span class="p">);</span>
<span class="w">    </span><span class="k">constexpr</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">imgHeight</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">16</span><span class="p">;</span>
<span class="w">    </span><span class="k">for</span><span class="w"> </span><span class="p">(</span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">&lt;</span><span class="w"> </span><span class="n">imgHeight</span><span class="p">;</span><span class="w"> </span><span class="o">++</span><span class="n">i</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">        </span><span class="n">asc_copy_gm2ub_align</span><span class="p">(</span><span class="n">tensorIn</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">copyWidth</span><span class="p">,</span><span class="w"> </span><span class="n">tensorGM</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">imgWidth</span><span class="p">,</span>
<span class="w">            </span><span class="n">copyWidth</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="k">sizeof</span><span class="p">(</span><span class="kt">float</span><span class="p">));</span>
<span class="w">    </span><span class="p">}</span>
<span class="w">    </span><span class="n">asc_sync_pipe</span><span class="p">(</span><span class="n">PIPE_ALL</span><span class="p">);</span>
<span class="p">}</span>
</code></pre></div><p>【正例】</p><p>一次提交16个数据块，每块2048字节；源行首间距16384字节，目的行首间距2048字节。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">CopyRowsCGood</span><span class="p">(</span><span class="n">__ubuf__</span><span class="w"> </span><span class="kt">float</span><span class="o">*</span><span class="w"> </span><span class="n">tensorIn</span><span class="p">,</span><span class="w"> </span><span class="n">__gm__</span><span class="w"> </span><span class="kt">float</span><span class="o">*</span><span class="w"> </span><span class="n">tensorGM</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="k">constexpr</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">copyWidth</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">2</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="mi">1024</span><span class="w"> </span><span class="o">/</span><span class="w"> </span><span class="k">sizeof</span><span class="p">(</span><span class="kt">float</span><span class="p">);</span>
<span class="w">    </span><span class="k">constexpr</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">imgWidth</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">16</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="mi">1024</span><span class="w"> </span><span class="o">/</span><span class="w"> </span><span class="k">sizeof</span><span class="p">(</span><span class="kt">float</span><span class="p">);</span>
<span class="w">    </span><span class="k">constexpr</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">imgHeight</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">16</span><span class="p">;</span>
<span class="w">    </span><span class="n">asc_copy_gm2ub_align</span><span class="p">(</span><span class="n">tensorIn</span><span class="p">,</span><span class="w"> </span><span class="n">tensorGM</span><span class="p">,</span><span class="w"> </span><span class="n">imgHeight</span><span class="p">,</span><span class="w"> </span><span class="n">copyWidth</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="k">sizeof</span><span class="p">(</span><span class="kt">float</span><span class="p">),</span>
<span class="w">        </span><span class="mi">0</span><span class="p">,</span><span class="w"> </span><span class="mi">0</span><span class="p">,</span><span class="w"> </span><span class="nb">false</span><span class="p">,</span><span class="w"> </span><span class="n">asc_load_l2_cache_mode</span><span class="o">::</span><span class="n">NORMAL_FIRST_VICTIM</span><span class="p">,</span>
<span class="w">        </span><span class="n">imgWidth</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="k">sizeof</span><span class="p">(</span><span class="kt">float</span><span class="p">),</span><span class="w"> </span><span class="n">copyWidth</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="k">sizeof</span><span class="p">(</span><span class="kt">float</span><span class="p">));</span>
<span class="w">    </span><span class="n">asc_sync_pipe</span><span class="p">(</span><span class="n">PIPE_ALL</span><span class="p">);</span>
<span class="p">}</span>
</code></pre></div><p>采用该方式时，需要注意以下事项：</p><ul><li>本节950接口的长度和步长均以字节为单位，步长表示相邻块首地址间距，不是块间空隙。</li><li>UB至少容纳32KB有效数据，块数、块长度及步长必须满足接口范围。</li><li>使用搬运结果前需保证搬入完成；片段末尾等待流水完成。</li></ul></div><h3 id="Basic-API">Basic API<a class="header-anchor" href="#Basic-API">​</a></h3><p>通过DataCopy搬运数据，以DataCopyParams配置块数、块长度和块间间隔。<code>tensorGM</code>已关联GM输入，<code>tensorIn</code>已分配至少8192个float，起始地址32字节对齐；以下片段使用<code>kernel_operator.h</code>和<code>AscendC</code>命名空间。</p><p>【反例】</p><p>每次搬运一行的有效数据，循环提交16次DataCopy。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">constexpr</span><span class="w"> </span><span class="kt">int32_t</span><span class="w"> </span><span class="n">copyWidth</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">2</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="mi">1024</span><span class="w"> </span><span class="o">/</span><span class="w"> </span><span class="k">sizeof</span><span class="p">(</span><span class="kt">float</span><span class="p">);</span>
<span class="k">constexpr</span><span class="w"> </span><span class="kt">int32_t</span><span class="w"> </span><span class="n">imgWidth</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">16</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="mi">1024</span><span class="w"> </span><span class="o">/</span><span class="w"> </span><span class="k">sizeof</span><span class="p">(</span><span class="kt">float</span><span class="p">);</span>
<span class="k">constexpr</span><span class="w"> </span><span class="kt">int32_t</span><span class="w"> </span><span class="n">imgHeight</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">16</span><span class="p">;</span>
<span class="k">for</span><span class="w"> </span><span class="p">(</span><span class="kt">int32_t</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">&lt;</span><span class="w"> </span><span class="n">imgHeight</span><span class="p">;</span><span class="w"> </span><span class="o">++</span><span class="n">i</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">    </span><span class="n">DataCopy</span><span class="p">(</span><span class="n">tensorIn</span><span class="p">[</span><span class="n">i</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">copyWidth</span><span class="p">],</span><span class="w"> </span><span class="n">tensorGM</span><span class="p">[</span><span class="n">i</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">imgWidth</span><span class="p">],</span><span class="w"> </span><span class="n">copyWidth</span><span class="p">);</span>
<span class="p">}</span>
</code></pre></div><p>【正例】</p><p>通过DataCopyParams一次提交16行的搬运。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">constexpr</span><span class="w"> </span><span class="kt">int32_t</span><span class="w"> </span><span class="n">copyWidth</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">2</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="mi">1024</span><span class="w"> </span><span class="o">/</span><span class="w"> </span><span class="k">sizeof</span><span class="p">(</span><span class="kt">float</span><span class="p">);</span>
<span class="k">constexpr</span><span class="w"> </span><span class="kt">int32_t</span><span class="w"> </span><span class="n">imgWidth</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">16</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="mi">1024</span><span class="w"> </span><span class="o">/</span><span class="w"> </span><span class="k">sizeof</span><span class="p">(</span><span class="kt">float</span><span class="p">);</span>
<span class="k">constexpr</span><span class="w"> </span><span class="kt">int32_t</span><span class="w"> </span><span class="n">imgHeight</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">16</span><span class="p">;</span>
<span class="n">DataCopyParams</span><span class="w"> </span><span class="n">copyParams</span><span class="p">;</span>
<span class="n">copyParams</span><span class="p">.</span><span class="n">blockCount</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">imgHeight</span><span class="p">;</span>
<span class="n">copyParams</span><span class="p">.</span><span class="n">blockLen</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">copyWidth</span><span class="w"> </span><span class="o">/</span><span class="w"> </span><span class="mi">8</span><span class="p">;</span><span class="w"> </span><span class="c1">// 单位为32字节，每块有8个float。</span>
<span class="n">copyParams</span><span class="p">.</span><span class="n">srcStride</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="p">(</span><span class="n">imgWidth</span><span class="w"> </span><span class="o">-</span><span class="w"> </span><span class="n">copyWidth</span><span class="p">)</span><span class="w"> </span><span class="o">/</span><span class="w"> </span><span class="mi">8</span><span class="p">;</span><span class="w"> </span><span class="c1">// 源块间空隙，单位为32字节。</span>
<span class="n">copyParams</span><span class="p">.</span><span class="n">dstStride</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span><span class="w"> </span><span class="c1">// 目的数据块连续排列。</span>
<span class="n">DataCopy</span><span class="p">(</span><span class="n">tensorIn</span><span class="p">,</span><span class="w"> </span><span class="n">tensorGM</span><span class="p">,</span><span class="w"> </span><span class="n">copyParams</span><span class="p">);</span>
</code></pre></div><p>采用该方式时，需要注意以下事项：</p><ul><li>此处DataCopyParams的块长度与块间间隔以32字节为单位，不能照搬950 C API的字节步长。</li><li>源、目的参数顺序为目的LocalTensor在前、源GlobalTensor在后。</li><li>使用搬运结果前需通过队列或事件保证搬入完成。</li></ul></article></div>`,1)])])}const m=a(t,[["render",o]]);export{_ as __pageData,m as default};
